/*
 Problem: 3310. Remove Methods From Project
 Language: cpp
 Runtime: 803 ms (5.05%)
 Memory: 324.3 MB (46.30%)
 Tags: Depth-First Search, Breadth-First Search, Graph Theory
*/
class Solution {
public:
    vector<int> remainingMethods(int n, int k, vector<vector<int>>& invocations) {
        vector<vector<int>> graph(n);

        for (const auto& e : invocations) {
            graph[e[0]].push_back(e[1]);
        }

        vector<bool> suspicious(n, false);

        function<void(int)> dfs = [&](int u) {
            suspicious[u] = true;
            for (int v : graph[u]) {
                if (!suspicious[v]) {
                    dfs(v);
                }
            }
        };

        dfs(k);

        for (const auto& e : invocations) {
            int u = e[0];
            int v = e[1];
            if (!suspicious[u] && suspicious[v]) {
                vector<int> ans;
                for (int i = 0; i < n; i++) {
                    ans.push_back(i);
                }
                return ans;
            }
        }

        vector<int> ans;
        for (int i = 0; i < n; i++) {
            if (!suspicious[i]) {
                ans.push_back(i);
            }
        }

        return ans;
    }
};
